import{_ as t}from"./chunks/settings-gamepad.pc.ko.BNw-kDrv.js";import{_ as e,o as d,c as a,a5 as r}from"./chunks/framework.BjM_ivYE.js";const c="/RBQ/images/app/home-gamepad.mobile.ko.png",_=JSON.parse('{"title":"게임패드","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/gamepad.md","filePath":"ko/manual/gui/gamepad.md","lastUpdated":1790671200000}'),n={name:"ko/manual/gui/gamepad.md"};function s(l,o,i,p,g,m){return d(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="게임패드" tabindex="-1">게임패드 <a class="header-anchor" href="#게임패드" aria-label="Permalink to &quot;게임패드&quot;">​</a></h1><p>앱은 기본적으로 화면의 가상 조이스틱으로 로봇을 조종합니다. 물리 게임패드를 연결하면 별도 설정 없이 자동으로 게임패드로 전환됩니다.</p><h2 id="자동-인식" tabindex="-1">자동 인식 <a class="header-anchor" href="#자동-인식" aria-label="Permalink to &quot;자동 인식&quot;">​</a></h2><ul><li>게임패드를 USB 또는 블루투스로 연결합니다. 앱이 즉시 기기를 인식해 맞는 프로파일을 적용하고 <strong>가상 조이스틱을 숨깁니다</strong>.</li><li>연결을 해제하면 가상 조이스틱이 자동으로 다시 나타납니다.</li><li>게임패드가 활성인 동안 제어 홈에서 눈에 띄는 변화는 가상 조이스틱이 그려지지 않는 것뿐입니다. 카드와 뷰포트는 그대로입니다. 기기 이름과 스틱·버튼을 실시간으로 그려 주는 다이어그램은 아래 <code>조종</code> 팝오버에 있습니다.</li></ul><p><img src="'+c+'" alt="게임패드 모드의 제어 홈 — 가상 조이스틱 숨김"></p><p>연결 상태는 <strong>앱 설정</strong>(오른쪽 위 톱니바퀴 버튼) › <code>게임패드</code>(<code>Gamepad</code>)에서 확인합니다. 상태 줄에는 <code>연결됨</code>과 기기 이름이, 연결이 없으면 <code>연결된 게임패드 없음 — 가상 조이스틱 사용 중</code>이 표시됩니다. 그 아래 <code>적용 프로파일:</code>은 어떤 버튼·축 배치가 골라졌는지 <code>(자동 인식)</code>과 함께 알려 줍니다.</p><p><img src="'+t+'" alt="게임패드 설정"></p><h2 id="입력-모드-선택" tabindex="-1">입력 모드 선택 <a class="header-anchor" href="#입력-모드-선택" aria-label="Permalink to &quot;입력 모드 선택&quot;">​</a></h2><p>자동 선택을 덮어쓸 수 있는 곳이 두 군데 있습니다.</p><ul><li><strong>앱 설정 › <code>게임패드</code> › <code>조이스틱 모드</code></strong>(<code>Joystick mode</code>) — <code>자동</code> / <code>가상 조이스틱</code> / <code>게임패드</code>. <em>UI 레이아웃만</em> 지정하며, 연결된 입력 장치는 그대로 동작합니다.</li><li><strong>제어 홈 › <code>조종</code></strong>(<code>CONTROL INPUT</code>, 왼쪽 카드 <strong>밖</strong> 도구 줄의 게임패드 버튼 — 왼쪽 조이스틱 오른쪽, 게임패드를 쓰면 화면 왼쪽 가장자리) — 같은 선택을 <code>자동</code> / <code>가상</code> / <code>패드</code>로 고릅니다. 게임패드가 연결돼 있고 조이스틱 모드가 <code>가상 조이스틱</code>으로 지정되지 않았다면, 이 팝오버에 앱이 받고 있는 입력을 보여주는 다이어그램도 함께 뜹니다.</li></ul><p>문제를 살펴보는 중이 아니라면 <code>자동</code>으로 두십시오.</p><h2 id="안전-버튼-세트" tabindex="-1">안전 버튼 세트 <a class="header-anchor" href="#안전-버튼-세트" aria-label="Permalink to &quot;안전 버튼 세트&quot;">​</a></h2><p>기본 상태에서 앱은 스틱과 함께 숄더 버튼 두 개(<strong>L1 / R1</strong>)만 로봇에 전달합니다. 나머지 버튼은 조이스틱 프레임에서 빠지므로 실수로 눌러도 로봇 쪽 버튼 동작이 실행되지 않습니다. 단, 개발자가 <code>버튼 매핑</code>으로 할당한 버튼과 <code>크루즈 컨트롤</code> 키는 이 설정과 무관하게 동작합니다.</p><p><strong>개발자 모드</strong>로 올라가면 <code>전체 버튼 전송</code>(<code>Send all buttons</code>)이 자동으로 켜져 모든 버튼이 로봇으로 갑니다. 로봇이 숄더 버튼과 함께 읽는 조합(예: <strong>L1 + B</strong>)은 이 설정이 켜져 있어야 동작합니다. 꺼져 있으면 조합의 나머지 버튼이 프레임에 실리지 않아 아무 일도 일어나지 않습니다. 일반 사용자로 돌아가면 다시 안전 모드가 됩니다. 설정은 <a href="/RBQ/ko/manual/gui/developer-mode.html#gamepad">개발자 모드</a>에 있습니다.</p><h2 id="스팀덱에서-글자-입력" tabindex="-1">스팀덱에서 글자 입력 <a class="header-anchor" href="#스팀덱에서-글자-입력" aria-label="Permalink to &quot;스팀덱에서 글자 입력&quot;">​</a></h2><p>스팀덱에서는 앱이 자체 화면 자판을 그립니다. 입력 칸을 누르면 화면 아래에 자판이 뜨고, 한글·영문·숫자·기호를 넣을 수 있습니다. 편집 중인 팝업은 자판 위로 올라갑니다. 지금 입력 중인 칸은 파란 테두리로 표시됩니다 — 깜빡이는 커서가 없는 것은 자판이 일부러 포커스를 잡지 않기 때문입니다.</p><p>게임패드로도 조작할 수 있습니다.</p><table tabindex="0"><thead><tr><th>조작</th><th>동작</th></tr></thead><tbody><tr><td>십자키</td><td>키 사이 이동</td></tr><tr><td><strong>A</strong></td><td>선택한 키 입력</td></tr><tr><td><strong>B</strong></td><td>자판 닫기</td></tr><tr><td><strong>X</strong></td><td>지우기</td></tr><tr><td><strong>Y</strong></td><td>공백</td></tr><tr><td><strong>L1</strong></td><td>시프트</td></tr><tr><td><strong>R1</strong></td><td>한글 / 영문 전환</td></tr></tbody></table><p><code>123</code>과 <code>한</code> / <code>A</code> 는 지금 상태가 아니라 <strong>누르면 갈 곳</strong>을 표시하며, 숫자판에서 나올 때는 마지막에 쓰던 언어로 돌아갑니다. <code>✓</code> 는 확인입니다 — 팝업에 확인 버튼이 있으면 그 버튼을 누르고, 없으면 입력을 제출합니다.</p><p>자판이 떠 있는 동안 게임패드는 자판이 가져갑니다 — 스틱·버튼이 로봇으로 가지 않으므로 글자를 고르는 동안 로봇이 움직이지 않습니다. 다른 기기에서는 종전처럼 운영체제 자판을 씁니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/ko/manual/gui/developer-mode.html#gamepad">개발자 모드</a>에 모아 두었습니다.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>전체 버튼 전송</code>과 <code>크루즈 컨트롤</code>은 버튼을 눌렀을 때 로봇이 보이는 반응을 바꿉니다. 켠 뒤에는 넓은 공간에서 먼저 시험하고, E-STOP을 바로 누를 수 있는 위치에 두십시오.</p></div>',22)])])}const b=e(n,[["render",s]]);export{_ as __pageData,b as default};
